<template>
<section class="ventas"><header class="encabezado"><div><h1>Ventas por Punto de Venta</h1><p>Registra ventas únicamente sobre existencias recibidas y disponibles.</p></div></header>
<div v-if="error" class="alerta">{{error}}</div><div v-if="exito" class="correcto">{{exito}}</div>
<div class="panel"><router-link to="/cobros-ventas" class="btn">Ir a Caja y Cobros</router-link></div>
<div class="panel"><h2>Nueva venta</h2><label>Punto de venta asignado</label><select v-model="stand" @change="cargarStock"><option value="">Seleccione un punto de venta</option><option v-for="s in stands" :key="s.id_ubicacion" :value="s.id_ubicacion">{{s.evento?.nombre || s.tipo}} · {{s.nombre}}</option></select>
<div v-if="stand"><div class="cabecera-lineas"><h3>Productos disponibles</h3><button class="btn" @click="cargarStock">Actualizar existencias</button></div>
<div class="tabla"><table><thead><tr><th>Producto / presentación</th><th>Lote</th><th>Disponible</th><th>Precio (Bs)</th><th>Cantidad a vender</th></tr></thead><tbody>
<tr v-for="i in stock" :key="i.id_lote"><td>{{i.lote?.presentacion?.producto?.nombre || i.lote?.presentacion?.nombre_presentacion || 'Producto'}} · {{i.lote?.presentacion?.nombre_presentacion}}</td><td>{{i.lote?.codigo_lote}}</td><td>{{i.stock_actual}}</td><td>{{moneda(i.lote?.presentacion?.precio_unitario)}}</td><td><input type="number" min="0" :max="i.stock_actual" step="1" v-model.number="cantidades[i.id_lote]" /></td></tr>
<tr v-if="!stock.length"><td colspan="5">No hay existencias disponibles en esta ubicación.</td></tr></tbody></table></div>
<label>Observación (opcional)</label><textarea v-model="observacion" maxlength="1000" placeholder="Detalle de la venta"></textarea>
<div class="pago"><label>Método de pago (cobro inmediato)</label><select v-model="metodoPago"><option value="EFECTIVO">Efectivo</option><option value="QR">QR</option><option value="TRANSFERENCIA">Transferencia</option></select><label v-if="metodoPago!=='EFECTIVO'">Referencia del pago</label><input v-if="metodoPago!=='EFECTIVO'" v-model="referenciaPago" maxlength="120" placeholder="N.º de operación"/><p class="leyenda">Requiere caja abierta. Venta, stock y cobro se registran juntos.</p></div><div class="pie"><strong>Total estimado: Bs {{moneda(total)}}</strong><button class="btn principal" :disabled="guardando || !lineas.length" @click="registrar">{{guardando?'Registrando...':'Confirmar venta'}}</button></div></div></div>
<div class="panel"><div class="cabecera-lineas"><h2>Historial de ventas</h2><button class="btn" @click="cargarVentas">Actualizar</button></div><div class="filtros"><label>Desde <input type="date" v-model="filtros.fecha_desde"></label><label>Hasta <input type="date" v-model="filtros.fecha_hasta"></label><label>Estado <select v-model="filtros.estado"><option value="">Todos</option><option value="CONFIRMADA">Confirmada</option><option value="ANULADA">Anulada</option></select></label><button class="btn" @click="cargarVentas">Filtrar</button></div><div class="tabla"><table><thead><tr><th>N.º</th><th>Fecha</th><th>Stand</th><th>Usuario</th><th>Estado</th><th>Total (Bs)</th><th>Acciones</th></tr></thead><tbody><tr v-for="v in ventas" :key="v.id_venta"><td>#{{v.id_venta}}</td><td>{{new Date(v.fecha_venta).toLocaleString('es-BO')}}</td><td>{{v.ubicacion?.nombre}}</td><td>{{v.usuario?.name}}</td><td>{{v.estado}}</td><td>{{moneda(v.total)}}</td><td><button class="btn" @click="verDetalle(v.id_venta)">Detalle</button> <button v-if="v.estado==='CONFIRMADA' && puedeAnular" class="btn peligro" @click="anular(v)">Anular</button></td></tr><tr v-if="!ventas.length"><td colspan="7">Sin ventas registradas.</td></tr></tbody></table></div></div>
<div v-if="detalle" class="panel" id="detalle-venta"><div class="cabecera-lineas"><h2>Detalle de venta #{{detalle.id_venta}}</h2><div><button class="btn" @click="imprimir">Imprimir comprobante interno</button> <button class="btn" @click="detalle=null">Cerrar</button></div></div><p><strong>Fecha:</strong> {{new Date(detalle.fecha_venta).toLocaleString('es-BO')}} · <strong>Estado:</strong> {{detalle.estado}}</p><p><strong>Stand:</strong> {{detalle.ubicacion?.evento?.nombre}} · {{detalle.ubicacion?.nombre}} · <strong>Vendedor:</strong> {{detalle.usuario?.name}}</p><div class="tabla"><table><thead><tr><th>Producto</th><th>Lote</th><th>Cantidad</th><th>Precio (Bs)</th><th>Subtotal (Bs)</th></tr></thead><tbody><tr v-for="d in detalle.detalles" :key="d.id_detalle_venta"><td>{{d.lote?.presentacion?.producto?.nombre}} · {{d.lote?.presentacion?.nombre_presentacion}}</td><td>{{d.lote?.codigo_lote}}</td><td>{{d.cantidad}}</td><td>{{moneda(d.precio_unitario)}}</td><td>{{moneda(d.subtotal)}}</td></tr></tbody></table></div><p><strong>Total: Bs {{moneda(detalle.total)}}</strong></p><p v-if="detalle.observacion">Observación: {{detalle.observacion}}</p><p v-if="detalle.estado==='ANULADA'">Anulada por {{detalle.usuario_anulacion?.name}} el {{new Date(detalle.fecha_anulacion).toLocaleString('es-BO')}}. Motivo: {{detalle.motivo_anulacion}}</p><p class="leyenda">Comprobante interno de control. No es factura fiscal.</p></div>
</section>
</template>
<script>
import api from '../../services/api';
export default {data(){return {stands:[],stand:'',stock:[],cantidades:{},observacion:'',ventas:[],error:'',exito:'',guardando:false,detalle:null,filtros:{fecha_desde:'',fecha_hasta:'',estado:''},puedeAnular:false,metodoPago:'EFECTIVO',referenciaPago:''}},computed:{lineas(){return this.stock.filter(i=>Number(this.cantidades[i.id_lote])>0).map(i=>({id_lote:i.id_lote,cantidad:Number(this.cantidades[i.id_lote])}))},total(){return this.stock.reduce((s,i)=>s+(Number(this.cantidades[i.id_lote])||0)*Number(i.lote?.presentacion?.precio_unitario||0),0)}},async mounted(){try{const {data}=await api.get('/api/ventas-stand/stands');this.stands=data;if(data.length===1){this.stand=data[0].id_ubicacion;await this.cargarStock()}await this.cargarVentas();await this.cargarPermisos()}catch(e){this.error=e.response?.data?.message||'No se pudieron cargar los stands.'}},methods:{async cargarPermisos(){try{const {data}=await api.get('/api/usuario');const roles=data.roles||[];const permisos=data.permissions||data.permisos||[];this.puedeAnular=roles.some(r=>(typeof r==='string'?r:r.name)==='ADMIN')}catch(e){this.puedeAnular=false}},async verDetalle(id){this.error='';try{const {data}=await api.get(`/api/ventas-stand/${id}`);this.detalle=data;this.$nextTick(()=>document.getElementById('detalle-venta')?.scrollIntoView({behavior:'smooth'}))}catch(e){this.error=e.response?.data?.message||'No se pudo consultar el detalle.'}},async anular(v){const motivo=prompt(`Motivo de anulación de la venta #${v.id_venta} (mínimo 10 caracteres):`);if(motivo===null)return;if(motivo.trim().length<10){this.error='El motivo debe tener al menos 10 caracteres.';return}if(!confirm('¿Anular esta venta y devolver las existencias al stand?'))return;try{await api.post(`/api/ventas-stand/${v.id_venta}/anular`,{motivo_anulacion:motivo.trim()});this.exito=`Venta #${v.id_venta} anulada y stock restituido.`;this.detalle=null;await this.cargarVentas();await this.cargarStock()}catch(e){this.error=e.response?.data?.message||'No se pudo anular la venta.'}},imprimir(){if(!this.detalle)return;const d=this.detalle;const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const filas=(d.detalles||[]).map(x=>`<tr><td>${esc(x.lote?.presentacion?.producto?.nombre)} / ${esc(x.lote?.codigo_lote)}</td><td>${esc(x.cantidad)}</td><td>${esc(x.precio_unitario)}</td><td>${esc(x.subtotal)}</td></tr>`).join('');const html=`<!doctype html><html><head><meta charset="utf-8"><title>Comprobante interno #${d.id_venta}</title><style>body{font:14px Arial;padding:25px;color:#12382b}table{width:100%;border-collapse:collapse}td,th{border-bottom:1px solid #ddd;padding:8px;text-align:left}</style></head><body><h2>EXCERNAT · Comprobante interno #${d.id_venta}</h2><p>No válido como factura fiscal</p><p>Fecha: ${esc(new Date(d.fecha_venta).toLocaleString('es-BO'))}</p><p>Stand: ${esc(d.ubicacion?.nombre)} · Vendedor: ${esc(d.usuario?.name)}</p><p>Estado: ${esc(d.estado)}</p><table><thead><tr><th>Producto / lote</th><th>Cant.</th><th>Precio Bs</th><th>Subtotal Bs</th></tr></thead><tbody>${filas}</tbody></table><h3>Total: Bs ${esc(d.total)}</h3></body></html>`;const ventana=window.open('','_blank');if(!ventana){this.error='Permita ventanas emergentes para imprimir.';return}ventana.document.write(html);ventana.document.close();ventana.focus();ventana.print()},moneda(v){return Number(v||0).toFixed(2)},async cargarStock(){this.detalle=null;await this.cargarVentas();this.error='';this.stock=[];this.cantidades={};if(!this.stand)return;try{const {data}=await api.get('/api/ventas-stand/existencias',{params:{id_ubicacion:this.stand}});this.stock=data}catch(e){this.error=e.response?.data?.message||'No se pudieron consultar existencias.'}},async cargarVentas(){try{const {data}=await api.get('/api/ventas-stand',{params:{...(this.stand?{id_ubicacion:this.stand}:{}),...Object.fromEntries(Object.entries(this.filtros).filter(([,v])=>v))}});this.ventas=data.data||[]}catch(e){this.error=e.response?.data?.message||'No se pudo cargar el historial.'}},async registrar(){this.error='';this.exito='';if(this.lineas.some(x=>!Number.isInteger(x.cantidad)||x.cantidad<1)){this.error='Ingrese cantidades enteras mayores a cero.';return}if(this.lineas.some(x=>x.cantidad>this.stock.find(i=>i.id_lote===x.id_lote)?.stock_actual)){this.error='Una cantidad supera el stock disponible.';return}if(!this.stand){this.error='Seleccione un punto de venta.';return}if(this.metodoPago!=='EFECTIVO'&&!this.referenciaPago.trim()){this.error='Ingrese la referencia del pago.';return}if(!confirm(`¿Confirmar venta y cobro por Bs ${this.moneda(this.total)}?`))return;this.guardando=true;try{const {data}=await api.post('/api/ventas-stand',{id_ubicacion:this.stand,observacion:this.observacion||null,detalles:this.lineas,pago:{metodo_pago:this.metodoPago,referencia:this.referenciaPago||null,clave_operacion:'VENTA-'+Date.now()+'-'+Math.random().toString(36).slice(2)}});this.exito=`Venta #${data.venta.id_venta} confirmada y cobrada.`;this.observacion='';this.referenciaPago='';await this.cargarStock();await this.cargarVentas()}catch(e){this.error=e.response?.data?.message||'No se pudo registrar la venta.'}finally{this.guardando=false}}}}
</script>
<style scoped>
.pago{margin-top:18px;padding:15px;border:1px solid #d7e7dc;border-radius:10px;background:#f3f8f4}.pago input{max-width:360px;width:100%}.ventas{max-width:1450px;margin:auto;padding:24px;color:#0c3025}.encabezado h1{font-size:30px;margin:0}.encabezado p{color:#60776a}.panel{background:#fff;border:1px solid #dce8df;border-radius:16px;padding:24px;margin:20px 0;box-shadow:0 6px 24px #103a2d0b}h2{font-size:20px;margin:0 0 18px}h3{font-size:16px}label{display:block;font-weight:700;margin:12px 0 7px}select,textarea,input{border:1px solid #cadcd0;border-radius:8px;padding:10px;font:inherit}select,textarea{width:100%}textarea{min-height:72px}.tabla{overflow-x:auto;margin-top:15px}table{width:100%;border-collapse:collapse}th{background:#0c3025;color:white;text-align:left}th,td{padding:12px;border-bottom:1px solid #e2ebe5}input{max-width:115px}.cabecera-lineas,.pie{display:flex;justify-content:space-between;align-items:center;gap:15px;flex-wrap:wrap}.pie{margin-top:20px}.btn{border:1px solid #c8d9ce;background:white;color:#124734;border-radius:9px;padding:10px 15px;font-weight:700;cursor:pointer}.principal{background:#f47b20;border-color:#f47b20;color:white}.btn:disabled{opacity:.5;cursor:not-allowed}.filtros{display:flex;gap:12px;align-items:end;flex-wrap:wrap;margin:12px 0}.filtros label{margin:0}.filtros input,.filtros select{display:block;min-width:135px}.peligro{color:#a52c2c;border-color:#e9b2b2}.leyenda{font-size:12px;color:#667}.alerta,.correcto{padding:12px;border-radius:8px;margin:12px 0}.alerta{background:#ffeded;color:#a22}.correcto{background:#e9f6ee;color:#175b3b}@media(max-width:700px){.ventas{padding:12px}.panel{padding:14px}}
</style>
